-- =============================================================================
-- 528 — LE CAHIER D'EXERCICES DE 1RE (partie 16)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/1re/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 528 --niveau 1re --fichiers francais.n20b,francais.n21a,francais.n21b,francais.n22a,francais.n22b --suffixe 16 > supabase/contenu/528_exercices_1re_16.sql
--
-- 90 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   francais.n20b           18 exercices · 6 chapitres
--   francais.n21a           18 exercices · 6 chapitres
--   francais.n21b           18 exercices · 6 chapitres
--   francais.n22a           18 exercices · 6 chapitres
--   francais.n22b           18 exercices · 6 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('143674d9-be7f-57c6-b345-6740660203cd'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Vérone, deux familles","competence":"analyser-document","situation":"Tu fiches *Roméo et Juliette*. Lis la carte de la pièce, puis le tableau qui range les personnages par famille.","documents":[{"id":"carte","type":"fiche","modele":"affiche","entete":"Roméo et Juliette","sousTitre":"William Shakespeare (1564-1616)","emoji":"🌹","lignes":[{"texte":"Composition","valeur":"Vers 1595"},{"texte":"Lieu de l’action","valeur":"Vérone","id":"z1"},{"texte":"Durée de l’action","valeur":"Environ cinq jours"},{"texte":"Source","valeur":"Un poème d’Arthur Brooke (1562)","id":"z2"}],"pied":"Tragédie de la jeunesse et de la hâte","teinte":"violet"},{"id":"familles","type":"tableau","titre":"Deux familles qui se haïssent","colonnes":["Personnage","Famille"],"lignes":[["Roméo","Les Montaigu"],["Juliette","Les Capulet"],["Tybalt, cousin de Juliette","?"]],"enteteLignes":true}],"questions":[{"enonce":"Sur la carte, touche la ligne qui dit dans quelle ville se passe l’action.","aide":"C’est une ville d’Italie.","type":"zone","document":"carte","multiple":false},{"enonce":"Combien d’années séparent le poème de Brooke (1562) de la composition de la pièce (vers 1595) ?","aide":"Soustrais les deux dates de la carte.","type":"nombre","unite":"ans"},{"enonce":"De quelle famille est Tybalt ? (case « ? »)","aide":"Tybalt est le cousin de Juliette.","type":"choix","options":[{"id":"a","texte":"Les Capulet"},{"id":"b","texte":"La famille du prince"},{"id":"c","texte":"Les Montaigu"},{"id":"d","texte":"La famille de Pâris"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"L’action se passe à **Vérone**, où Montaigu et Capulet se haïssent depuis des générations."},{"cle":{"type":"nombre","valeur":33,"tolerance":0},"affichage":"33 ans","explication":"1595 − 1562 = **33 ans** : Shakespeare reprend une histoire italienne déjà connue en Angleterre."},{"cle":{"type":"choix","ids":["a"]},"explication":"Cousin de Juliette, Tybalt appartient aux **Capulet**."}]$ex$::jsonb),
  ('143674d9-be7f-57c6-b345-6740660203cd'::uuid, 2, 2, 10, 35, 3,
