   $ex$[{"cle":{"type":"choix","ids":["b"]},"explication":"Pour échapper au mariage avec Pâris, Juliette **boit un philtre** qui la fait passer pour morte."},{"cle":{"type":"zone","ids":["z5"]},"explication":"La lettre ne parvient pas à Roméo : le **hasard** devient l’instrument du destin."},{"cle":{"type":"association","paires":{"g0":"d0","g1":"d1","g3":"d2","g2":"d3"}},"explication":"**Frère Laurent** concilie, **Mercutio** moque et maudit, la **nourrice** bavarde, **Tybalt** est violent."}]$ex$::jsonb),
  ('143674d9-be7f-57c6-b345-6740660203cd'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"À l’aube, il faut partir","competence":"argumenter","situation":"Une scène écrite à la manière de Shakespeare met en jeu l’aube qui sépare les amants. Lis-la, puis cherche ce qu’elle dit des registres de la pièce.","documents":[{"id":"aube","type":"texte","genre":"theatre","titre":"À l’aube","blocs":[{"didascalie":"Une chambre, à l’aube. Un jeune homme et une jeune fille se parlent à voix basse."},{"personnage":"Elle","replique":"Ce n’est pas encore le jour ; reste. L’oiseau qui chante n’annonce rien."},{"personnage":"Lui","replique":"Si je reste, on me tuera ; si je pars, je vivrai, mais loin de toi."},{"personnage":"Elle","replique":"Alors que le jour se fasse attendre !"}],"source":"Texte écrit pour l’exercice, à la manière de Shakespeare"},{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Sam","emoji":"👦","cote":"gauche"},{"nom":"Jade","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Sam","texte":"La pièce est purement lyrique : on n’y rit jamais."},{"qui":"Jade","texte":"Pas du tout : la nourrice et Mercutio mêlent les obscénités au lyrisme des amants."}]}],"questions":[{"enonce":"Touche le mot qui dit le danger que court le jeune homme s’il reste.","aide":"Un verbe au futur, après « on ».","type":"zone","document":"aube","multiple":false},{"enonce":"Range chaque élément de la pièce selon son registre.","aide":"Le cours dit que les obscénités voisinent avec le lyrisme des amants.","type":"categories","categories":[{"id":"c0","texte":"Registre lyrique"},{"id":"c1","texte":"Registre comique ou grivois"}],"items":[{"id":"i0","texte":"Les plaisanteries de Mercutio"},{"id":"i1","texte":"Les propos crus de la nourrice"},{"id":"i2","texte":"Les adieux des amants à l’aube"},{"id":"i3","texte":"La scène du balcon"}]},{"enonce":"Quelle remarque du dialogue le cours confirme-t-il ?","aide":"Relis le tableau du cours : « Ce que Shakespeare mêle ».","type":"choix","options":[{"id":"a","texte":"Sam a raison : la pièce est purement lyrique"},{"id":"b","texte":"Les deux : tout dépend des actes"},{"id":"c","texte":"Jade a raison : la pièce mêle les registres"},{"id":"d","texte":"Aucun des deux : la pièce est un pur comique"}],"multiple":false},{"enonce":"Quelle formule résume au mieux la hâte qui domine la pièce ?","aide":"Le cours donne la durée de l’action.","type":"choix","options":[{"id":"a","texte":"Tout se joue en un seul acte"},{"id":"b","texte":"Tout se joue en deux mois"},{"id":"c","texte":"Tout se joue en un an"},{"id":"d","texte":"Tout se joue en cinq jours"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m37"]},"explication":"Le jeune homme court un danger de mort : « on me **tuera** ». C’est le sort de Roméo, banni de Vérone."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0"}},"explication":"Les **amants** parlent un langage lyrique (l’aube, le balcon) ; **Mercutio** et la **nourrice** apportent le comique et le grivois."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le théâtre élisabéthain **mêle les registres** : obscénités de la nourrice et de Mercutio à côté du lyrisme des amants."},{"cle":{"type":"choix","ids":["d"]},"explication":"La tragédie de la jeunesse et de la **hâte** : tout se joue en **cinq jours**."}]$ex$::jsonb),
  ('148f2945-50c4-53da-afd7-f095113c539c'::uuid, 1, 1, 5, 20, 3,
