  ('148f2945-50c4-53da-afd7-f095113c539c'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Le stratagème de don Salluste","competence":"se-reperer-temps","situation":"Lis ce résumé écrit pour l’exercice, puis range les étapes du drame dans l’ordre.","documents":[{"id":"resume","type":"texte","genre":"recit","titre":"Le résumé du drame","blocs":["À Madrid, Salluste, chassé de la cour par la reine, organise une vengeance avec son valet Ruy Blas.","Il le fait passer pour don César de Bazan : Ruy Blas devient courtisan, puis Premier ministre. À l’acte III, il dénonce les ministres qui pillent l’Espagne. Il gouverne bien et la reine l’aime.","Salluste tend alors un piège pour déshonorer la reine ; Ruy Blas, démasqué, le tue, avoue sa condition et boit le poison."],"source":"Texte écrit pour l’exercice, d’après le cours"}],"questions":[{"enonce":"Touche le nom de celui qui organise la vengeance.","aide":"Il a été chassé de la cour par la reine.","type":"zone","document":"resume","multiple":false},{"enonce":"Remets dans l’ordre les étapes du drame.","aide":"Suis le résumé de bout en bout, de l’ascension à la mort.","type":"ordre","items":[{"id":"a","texte":"Il prononce le grand discours de l’acte III"},{"id":"b","texte":"Ruy Blas tue Salluste et s’empoisonne"},{"id":"c","texte":"Ruy Blas est présenté sous le nom de don César"},{"id":"d","texte":"Salluste tend un piège à la reine"},{"id":"e","texte":"Ruy Blas devient Premier ministre"}]},{"enonce":"Range chaque personnage : noble ou homme du peuple ?","aide":"Le héros est celui qui porte la livrée d’un valet.","type":"categories","categories":[{"id":"c0","texte":"Noble"},{"id":"c1","texte":"Homme du peuple"}],"items":[{"id":"i0","texte":"Don César de Bazan"},{"id":"i1","texte":"Marie de Neubourg, la reine"},{"id":"i2","texte":"Ruy Blas"},{"id":"i3","texte":"Don Salluste"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m2"]},"explication":"C’est **don Salluste**, grand d’Espagne chassé de la cour, qui monte le stratagème."},{"cle":{"type":"ordre","ids":["c","e","a","d","b"]},"explication":"Le **faux nom**, le **ministère**, le **discours** de l’acte III, le **piège**, puis la **mort** de Ruy Blas."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c0"}},"explication":"Salluste, don César et la reine sont de la noblesse ; **Ruy Blas** est un valet, un homme du peuple."}]$ex$::jsonb),
  ('148f2945-50c4-53da-afd7-f095113c539c'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Bon appétit, messieurs !","competence":"analyser-texte","situation":"À l’acte III, Ruy Blas prend la parole devant les ministres. Lis les trois vers, puis cherche ce qu’ils disent du pouvoir et de ceux qui l’exercent.","documents":[{"id":"tirade","type":"texte","genre":"theatre","titre":"Acte III, scène 2","blocs":[{"personnage":"Ruy Blas","replique":"Bon appétit, messieurs ! Ô ministres intègres !"},{"personnage":"Ruy Blas","replique":"Conseillers vertueux ! voilà votre façon"},{"personnage":"Ruy Blas","replique":"De servir, serviteurs qui pillez la maison !"}],"source":"Victor Hugo, *Ruy Blas* (1838), acte III, scène 2"},{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Inès","emoji":"👧","cote":"gauche"},{"nom":"Tom","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Inès","texte":"Cette pièce parle d’amour : elle n’a aucune portée politique."},{"qui":"Tom","texte":"Regarde la tirade : un valet accuse les puissants de piller l’État."}]}],"questions":[{"enonce":"Touche les deux adjectifs employés par ironie pour les ministres.","aide":"Ils les qualifient de vertueux alors qu’ils font le contraire.","type":"zone","document":"tirade","multiple":true},{"enonce":"Touche le verbe qui dit ce que Ruy Blas reproche aux ministres.","aide":"Ils s’emparent des biens qu’ils devraient protéger.","type":"zone","document":"tirade","multiple":false},{"enonce":"Qui a raison dans le débat ?","aide":"Qui parle dans la tirade, et à qui ?","type":"choix","options":[{"id":"a","texte":"Inès : la politique n’entre pas dans le drame romantique"},{"id":"b","texte":"Inès : la pièce ne parle que d’amour"},{"id":"c","texte":"Tom : la pièce a une portée politique"},{"id":"d","texte":"Aucun : la pièce est un pur divertissement"}],"multiple":false},{"enonce":"Relie chaque personnage à ce qu’il incarne.","aide":"Hugo fait de chacun une figure sociale.","type":"association","gauche":[{"id":"g0","texte":"Ruy Blas"},{"id":"g1","texte":"Don Salluste"},{"id":"g2","texte":"Don César"},{"id":"g3","texte":"La reine"}],"droite":[{"id":"d0","texte":"Une femme seule et délaissée par le roi"},{"id":"d1","texte":"La noblesse cynique et vengeresse"},{"id":"d2","texte":"Le noble déclassé, libre et joyeux"},{"id":"d3","texte":"Le peuple, génie sans nom"}]}]}$ex$::jsonb,
