 plainte personnelle, dans ce recueil ?","aide":"Le poète s’adresse à lui-même, puis au Christ.","type":"choix","options":[{"id":"a","texte":"Une satire"},{"id":"b","texte":"Une prière"},{"id":"c","texte":"Un récit de voyage"},{"id":"d","texte":"Un manifeste"}],"multiple":false}]}$ex$::jsonb,
