   $ex${"titre":"Pour faire un poème dadaïste","competence":"analyser-texte","situation":"Un professeur propose un atelier d’écriture dadaïste. Lis sa consigne (écrite pour l’exercice), puis range les refus du mouvement.","documents":[{"id":"recette","type":"texte","genre":"consigne","titre":"L’atelier","blocs":["Prenez un journal et des ciseaux. Découpez un article mot par mot.","Mettez les mots dans un sac et agitez doucement.","Sortez les mots un à un : c’est le hasard qui compose le poème."],"source":"Texte écrit pour l’exercice, à la manière de Tzara"},{"id":"refus","type":"tableau","titre":"Ce que Dada refuse","colonnes":["Ce qui est refusé"],"lignes":[["L’art"],["La logique"],["La morale et le bon goût"],["La psychologie"],["?"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui dit ce qui compose le poème dans cet atelier.","aide":"Ce n’est ni l’auteur ni une règle.","type":"zone","document":"recette","multiple":false},{"enonce":"Que faut-il écrire dans la dernière case du tableau ?","aide":"Dada ne signifie rien : que refuse-t-il donc au langage ?","type":"choix","options":[{"id":"a","texte":"Le rire du public"},{"id":"b","texte":"Le papier journal"},{"id":"c","texte":"Le sens lui-même"},{"id":"d","texte":"La ville de Zurich"}],"multiple":false},{"enonce":"Relie chaque figure à son rôle.","aide":"Chacun a sa façon de provoquer.","type":"association","gauche":[{"id":"g0","texte":"Tristan Tzara"},{"id":"g1","texte":"Hugo Ball"},{"id":"g2","texte":"Hans Arp"},{"id":"g3","texte":"Marcel Duchamp"}],"droite":[{"id":"d0","texte":"Le fondateur du Cabaret Voltaire, auteur de poèmes phonétiques"},{"id":"d1","texte":"Le poète-provocateur, auteur des manifestes"},{"id":"d2","texte":"Le peintre et sculpteur qui compose au hasard"},{"id":"d3","texte":"L’artiste qui expose un urinoir signé, *Fontaine*"}]}]}$ex$::jsonb,
