  ('e0c7a756-1ca6-58dc-8966-61cfb2245481'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Dire vrai, est-ce tout dire ?","competence":"argumenter","situation":"Pour un sujet sur l’autobiographie, tu veux montrer que se dire vrai est à la fois un courage et une construction. Appuie-toi sur Gide.","documents":[{"id":"phrase","type":"texte","genre":"article","titre":"Un avertissement de Gide","blocs":["Les Mémoires ne sont jamais qu’à demi sincères, si grand que soit le souci de vérité : tout est toujours plus compliqué qu’on ne le dit."],"source":"André Gide, *Si le grain ne meurt*, cité par le cours"},{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Lucie","emoji":"👧","cote":"gauche"},{"nom":"Adam","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Lucie","texte":"Se raconter, c’est tout dire, sans aucun filtre."},{"qui":"Adam","texte":"Gide sait que se raconter, c’est aussi composer."}]},{"id":"these","type":"tableau","titre":"Un argument à compléter","colonnes":["Thèse","Argument","Exemple"],"lignes":[["Se dire vrai exige du courage","Gide avoue publiquement son homosexualité","?"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui limite la sincérité des Mémoires.","aide":"Il dit que la sincérité n’est jamais complète.","type":"zone","document":"phrase","multiple":false},{"enonce":"Qui a raison dans le débat ?","aide":"La phrase de Gide parle d’une sincérité « à demi ».","type":"choix","options":[{"id":"a","texte":"Adam : il faut cacher la vérité"},{"id":"b","texte":"Lucie : se raconter, c’est tout dire"},{"id":"c","texte":"Adam : se raconter, c’est composer"},{"id":"d","texte":"Lucie : la sincérité est totale"}],"multiple":false},{"enonce":"Que faut-il écrire dans la case « Exemple » du tableau ?","aide":"L’aveu public d’une homosexualité, à cette époque, provoque une réaction.","type":"choix","options":[{"id":"a","texte":"Le livre est écrit sous un faux nom"},{"id":"b","texte":"Le livre fait scandale à sa publication"},{"id":"c","texte":"Le livre est interdit par l’Église protestante"},{"id":"d","texte":"Le livre est un succès sans polémique"}],"multiple":false},{"enonce":"Quel rapprochement le cours propose-t-il avec *Si le grain ne meurt* ?","aide":"Pense à l’autobiographie qui prétendait déjà tout dire.","type":"choix","options":[{"id":"a","texte":"Les *Confessions* de Rousseau"},{"id":"b","texte":"Les *Maximes* de La Rochefoucauld"},{"id":"c","texte":"Le *Cid* de Corneille"},{"id":"d","texte":"Les *Fables* de La Fontaine"}],"multiple":false}]}$ex$::jsonb,
