   $ex${"titre":"Le merle et les cerises","competence":"analyser-texte","situation":"Lis ce court texte écrit à la manière de Colette, puis cherche comment il célèbre le monde.","documents":[{"id":"jardin","type":"texte","genre":"recit","titre":"Dans le jardin","blocs":["Ma mère savait nommer chaque plante : le souci, la pivoine, le thym. Quand le merle venait aux cerises, elle le laissait faire, pour l’admirer."],"source":"Texte écrit pour l’exercice, à la manière de Colette"}],"questions":[{"enonce":"Touche les deux noms de fleurs qui montrent la précision de la mère.","aide":"Ce sont deux fleurs nommées exactement.","type":"zone","document":"jardin","multiple":true},{"enonce":"Pourquoi la mère laisse-t-elle le merle piller ses cerises ?","aide":"Le texte dit qu’elle le laisse faire pour l’admirer.","type":"choix","options":[{"id":"a","texte":"Elle préfère de loin les cerises aux merles"},{"id":"b","texte":"Elle l’admire plus qu’elle ne regrette ses cerises"},{"id":"c","texte":"Elle ne l’a jamais vu approcher de l’arbre"},{"id":"d","texte":"Elle veut le chasser sans faire de bruit"}],"multiple":false},{"enonce":"Relie chaque personnage à ce qui le définit.","aide":"Chaque membre de la famille a sa marque.","type":"association","gauche":[{"id":"g0","texte":"Sido"},{"id":"g1","texte":"Le Capitaine"},{"id":"g2","texte":"Achille"},{"id":"g3","texte":"Léo"}],"droite":[{"id":"d0","texte":"Le père, qui a perdu une jambe à la guerre d’Italie"},{"id":"d1","texte":"La mère, attentive à tout ce qui vit"},{"id":"d2","texte":"Le demi-frère aîné, devenu médecin"},{"id":"d3","texte":"Le frère rêveur, resté enfant"}]}]}$ex$::jsonb,
