  ('a6fdd68e-65c2-533d-b8b9-6b9f7f4eb3f4'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Célébrer, c’est nommer","competence":"argumenter","situation":"Ana pense que *Sido* ne célèbre rien puisque tout y est perdu. Jules la contredit. Tranche avec le tableau et le passage.","documents":[{"id":"pluie","type":"texte","genre":"recit","titre":"La maison vendue","blocs":["La maison est vendue et la mère n’est plus là ; pourtant le jardin garde ses couleurs, et l’odeur exacte de la pluie sur la poussière chaude."],"source":"Texte écrit pour l’exercice, à la manière de Colette"},{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Ana","emoji":"👧","cote":"gauche"},{"nom":"Jules","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Ana","texte":"Le livre est triste : tout est perdu, donc il ne célèbre rien."},{"qui":"Jules","texte":"Il s’écrit du côté de la perte, et c’est de là que vient sa lumière."}]},{"id":"these","type":"tableau","titre":"Un argument à compléter","colonnes":["Thèse","Argument","Exemple"],"lignes":[["Célébrer, c’est nommer précisément","Le monde se célèbre par le détail exact","?"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui nomme la sensation que le texte restitue avec précision.","aide":"Il ne s’agit ni d’un bruit ni d’une couleur.","type":"zone","document":"pluie","multiple":false},{"enonce":"Que faut-il écrire dans la case « Exemple » du tableau ?","aide":"Le cours oppose le nom exact au mot vague.","type":"choix","options":[{"id":"a","texte":"Pas « une mère » mais « une femme »"},{"id":"b","texte":"Pas « un jardin » mais une prairie sans nom"},{"id":"c","texte":"Pas « un merle » mais « un oiseau »"},{"id":"d","texte":"Pas « une fleur » mais un souci, une pivoine"}],"multiple":false},{"enonce":"Range chaque expression : Colette la choisit, ou l’évite ?","aide":"Le cours donne l’exemple du nom exact contre le mot vague.","type":"categories","categories":[{"id":"c0","texte":"Elle la choisit"},{"id":"c1","texte":"Elle l’évite"}],"items":[{"id":"i0","texte":"Une fleur"},{"id":"i1","texte":"Le printemps"},{"id":"i2","texte":"Une pivoine"},{"id":"i3","texte":"Un souci"},{"id":"i4","texte":"L’odeur exacte de la pluie sur la poussière chaude"}]},{"enonce":"Qui a raison dans le débat ?","aide":"Le cours dit que le livre s’écrit du côté de la perte.","type":"choix","options":[{"id":"a","texte":"Ana : le livre ne célèbre rien du tout"},{"id":"b","texte":"Ana : le livre est écrit du côté de la fête"},{"id":"c","texte":"Jules : le livre est un reportage sur la guerre"},{"id":"d","texte":"Jules : la perte est la source de la lumière du livre"}],"multiple":false}]}$ex$::jsonb,
