  ('67de0133-7bea-58a6-b523-443cd9b4592a'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le sonnet du soir, à la chandelle","competence":"analyser-texte","situation":"Lina doit commenter le plus célèbre sonnet du recueil. Elle lit les premiers vers, puis reconstitue la scène que le poète imagine.","documents":[{"id":"vers","type":"texte","genre":"poeme","titre":"Les quatre premiers vers","blocs":["Quand vous serez bien vieille, au soir, à la chandelle,","Assise auprès du feu, dévidant et filant,","Direz, chantant mes vers, en vous émerveillant :","Ronsard me célébrait du temps que j’étais belle."],"source":"Pierre de Ronsard, *Sonnets pour Hélène*, livre II (1578), vers 1 à 4 — orthographe modernisée"},{"id":"scene","type":"chaine","titre":"La scène imaginée par le poète","disposition":"colonne","noeuds":[{"id":"z1","texte":"Hélène, devenue vieille, file près du feu"},{"id":"z2","texte":"Elle s’émerveille qu’un poète l’ait chantée"},{"id":"z3","texte":"?"},{"id":"z4","texte":"Le poète lui conseille de vivre sans attendre"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"}]}],"questions":[{"enonce":"Touche le mot qui dit l’âge qu’Hélène aura dans la scène.","aide":"C’est un adjectif, dans le premier vers.","type":"zone","document":"vers","multiple":false},{"enonce":"Touche les deux participes qui disent ce qu’elle fait près du feu.","aide":"Ce sont deux gestes de travail du fil, au deuxième vers.","type":"zone","document":"vers","multiple":true},{"enonce":"Que faut-il écrire à la place de la case « ? » de la chaîne ?","aide":"Hélène vieille pense au poète qui l’aimait.","type":"choix","options":[{"id":"a","texte":"Elle oublie jusqu’au nom du poète qui l’a chantée"},{"id":"b","texte":"Elle regrette de l’avoir dédaigné"},{"id":"c","texte":"Elle brûle les vers du poète par colère"},{"id":"d","texte":"Elle quitte la cour de la reine pour le suivre"}],"multiple":false},{"enonce":"Complète la chute du sonnet.","aide":"La chute invite à profiter du temps présent.","type":"trous","segments":["La chute est un ",0," : « Cuei