   $ex$[{"cle":{"type":"zone","ids":["m4"]},"explication":"Le poète imagine Hélène **vieille** : tout le poème joue sur le temps qui passe."},{"cle":{"type":"zone","ids":["m14","m16"]},"explication":"Hélène est **dévidant** et **filant** : un geste humble, loin de la cour qu’elle fréquente aujourd’hui."},{"cle":{"type":"choix","ids":["b"]},"explication":"Dans la scène imaginée, Hélène **regrette de l’avoir dédaigné** : c’est la leçon que le poète lui adresse par avance."},{"cle":{"type":"trous","trous":[["carpe diem"],["roses"]]},"affichage":"carpe diem · roses","explication":"Le conseil final est un **carpe diem** : « cueillez dès aujourd’hui les **roses** de la vie »."}]$ex$::jsonb),
  ('67de0133-7bea-58a6-b523-443cd9b4592a'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"La poésie contre le temps","competence":"argumenter","situation":"Lina et Malik débattent du sens du sonnet. Les vers de Ronsard permettent de trancher.","documents":[{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Lina","emoji":"👧","cote":"gauche"},{"nom":"Malik","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Lina","texte":"C’est une simple déclaration d’amour : le poète supplie Hélène de l’aimer."},{"qui":"Malik","texte":"Pas seulement. Il imagine Hélène chantant ses vers : c’est le poème qui gardera sa beauté."},{"qui":"Lina","texte":"Mais elle sera vieille, alors la beauté aura disparu !"},{"qui":"Malik","texte":"Justement : le poème la conserve, pas le visage."}]},{"id":"vers","type":"texte","genre":"poeme","titre":"Les quatre premiers vers","blocs":["Quand vous serez bien vieille, au soir, à la chandelle,","Assise auprès du feu, dévidant et filant,","Direz, chantant mes vers, en vous émerveillant :","Ronsard me célébrait du temps que j’étais belle."],"source":"Pierre de Ronsard, *Sonnets pour Hélène*, livre II (1578), vers 1 à 4 — orthographe modernisée"}],"questions":[{"enonce":"Touche dans le poème le mot que Malik reprend dans sa réplique.","aide":"Malik dit ce qu’Hélène chantera.","type":"zone","document":"vers","multiple":false},{"enonce":"Touche le verbe qui montre que, pour Hélène vieille, le temps de la beauté est passé.","aide":"Le verbe est à l’imparfait.","type":"zone","document":"vers","multiple":false},{"enonce":"Relie chaque procédé à son effet dans ces quatre vers.","aide":"Observe le temps de chaque verbe.","type":"association","gauche":[{"id":"g0","texte":"Le futur « Quand vous serez »"},{"id":"g1","texte":"L’imparfait « célébrait »"},{"id":"g2","texte":"Les guillemets du dernier vers"}],"droite":[{"id":"d0","texte":"On entend Hélène rendre hommage au poète"},{"id":"d1","texte":"La beauté est déjà un souvenir"},{"id":"d2","texte":"Hélène est projetée dans sa propre vieillesse"}]},{"enonce":"Quelle réplique les vers confirment-ils ?","aide":"Que chante Hélène, une fois vieille ?","type":"choix","options":[{"id":"a","texte":"Malik : le poète renonce à toute gloire"},{"id":"b","texte":"Lina : le poème ne parle que de l’amour du poète"},{"id":"c","texte":"Lina : Hélène vieille oubliera le nom du poète"},{"id":"d","texte":"Malik : le poème conserve la beauté que le temps détruit"}],"multiple":false}]}$ex$::jsonb,
