"},{"id":"d2","texte":"Les deux interlocuteurs qui commentent le voyage"},{"id":"d3","texte":"Le Tahitien qui raisonne mieux que l’Européen"}]},{"enonce":"Touche la case qui dit ce que fait le vieillard.","aide":"Regarde la ligne « Les Adieux du vieillard ».","type":"zone","document":"morceaux","multiple":false}]}$ex$::jsonb,
