   $ex${"titre":"Tahiti est-il Tahiti ?","competence":"argumenter","situation":"Inès et Yanis ne lisent pas le texte de la même façon. Une phrase du vieillard leur permet de trancher.","documents":[{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Inès","emoji":"👧","cote":"gauche"},{"nom":"Yanis","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Inès","texte":"Diderot décrit Tahiti tel qu’il est : c’est une enquête sur place."},{"qui":"Yanis","texte":"Il n’y est jamais allé. Tahiti lui sert d’outil pour critiquer l’Europe."},{"qui":"Inès","texte":"Alors Tahiti serait un décor ?"},{"qui":"Yanis","texte":"Un miroir : les Tahitiens y semblent innocents et heureux."}]},{"id":"cit","type":"texte","genre":"source","titre":"Les Adieux du vieillard","blocs":["« Nous sommes innocents, nous sommes heureux ; et tu ne peux que nuire à notre bonheur. »"],"source":"Denis Diderot, *Supplément au voyage de Bougainville*, Adieux du vieillard — phrase donnée par le cours"}],"questions":[{"enonce":"Touche le mot de Yanis qui dit à quoi sert Tahiti dans le texte.","aide":"Yanis répond à Inès : Tahiti n’est pas décrit pour lui-même.","type":"zone","document":"deb","multiple":false},{"enonce":"Touche les deux mots du vieillard qui idéalisent les Tahitiens.","aide":"Ce sont deux adjectifs qui disent l’absence de faute et le bonheur.","type":"zone","document":"cit","multiple":true},{"enonce":"Quelle lecture la citation du vieillard soutient-elle ?","aide":"Un peuple entièrement « innocent » et « heureux » est-il une description réaliste ?","type":"choix","options":[{"id":"a","texte":"Yanis : Tahiti est un outil critique, largement idéalisé"},{"id":"b","texte":"Yanis : le texte défend le retour à l’état de nature"},{"id":"c","texte":"Inès : le texte est une enquête fidèle sur Tahiti"},{"id":"d","texte":"Inès : le vieillard décrit sa vie quotidienne"}],"multiple":false},{"enonce":"Range chaque idée sous la thèse du Supplément qu’elle illustre.","aide":"Trois thèses : ce que fait l’Europe, ce que sont nos mœurs, ce qu’il faut faire.","type":"categories","categories":[{"id":"c0","texte":"La colonisation est une prédation"},{"id":"c1","texte":"Nos mœurs sont conventionnelles"},{"id":"c2","texte":"Pas de retour à l’état de nature"}],"items":[{"id":"i0","texte":"La pudeur n’est pas une vérité naturelle"},{"id":"i1","texte":"Le mariage indissoluble est une institution"},{"id":"i2","texte":"Les Européens viennent corrompre le peuple tahitien"},{"id":"i3","texte":"Même si l’on sait qu’elles sont arbitraires"},{"id":"i4","texte":"Il faut suivre les lois de son pays"},{"id":"i5","texte":"« Ce pays est à toi ! Et pourquoi ? »"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m23"]},"explication":"Tahiti est un **outil** critique, pas une description ethnographique."},{"cle":{"type":"zone","ids":["m2","m5"]},"explication":"Les Tahitiens sont dits **innocents** et **heureux** : l’image est idéalisée, ce qui confirme que Tahiti sert la critique."},{"cle":{"type":"choix","ids":["a"]},"explication":"Un peuple sans faute ni malheur est une **image idéalisée** : Tahiti sert d’outil critique, non d’ethnographie."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c2","i4":"c2","i5":"c0"}},"explication":"Le vieillard dénonce la **prédation** ; Orou montre que mariage et pudeur sont des **institutions** ; la conclusion invite à **suivre les lois de son pays** tout en les sachant arbitraires."}]$ex$::jsonb),
