   $ex${"titre":"Un pilote de l’Aéropostale","competence":"se-reperer-temps","situation":"Tu fiches « Terre des hommes ». Place le livre dans la vie de Saint-Exupéry et retiens ce qu’il est.","documents":[{"id":"vie","type":"frise","titre":"Saint-Exupéry","debut":1900,"fin":1950,"pas":10,"evenements":[{"id":"z1","date":1900,"nom":"Naissance"},{"id":"z2","date":1926,"nom":"Aéropostale"},{"id":"z3","date":1939,"nom":"Terre des hommes"}]},{"id":"carte","type":"fiche","modele":"affiche","entete":"Terre des hommes","sousTitre":"Antoine de Saint-Exupéry","emoji":"🛩️","lignes":[{"texte":"Genre","valeur":"Récit de souvenirs et de méditations"},{"texte":"Ce que ce n’est pas","valeur":"Un roman"},{"texte":"Prix","valeur":"Grand Prix du roman de l’Académie française"},{"texte":"Compagnie","valeur":"Aéropostale"}],"pied":"Paru à la veille de la guerre","teinte":"violet"}],"questions":[{"enonce":"Touche l’année de parution de « Terre des hommes ».","aide":"Cherche l’événement qui porte le titre du livre.","type":"zone","document":"vie","multiple":false},{"enonce":"Combien d’années séparent l’entrée de Saint-Exupéry à l’Aéropostale de la parution du livre ?","aide":"Repère les deux dates sur la frise.","type":"nombre","unite":"ans"},{"enonce":"Comment la carte du livre définit-elle son genre ?","aide":"La carte dit aussi ce que le livre n’est pas.","type":"choix","options":[{"id":"a","texte":"Un récit de souvenirs et de méditations"},{"id":"b","texte":"Un roman d’aventures entièrement inventé"},{"id":"c","texte":"Un journal de guerre écrit au jour le jour"},{"id":"d","texte":"Un recueil de lettres à un ami"}],"multiple":false}]}$ex$::jsonb,
