   $ex${"titre":"Qui a marché, qui a disparu, qui a sauvé ?","competence":"analyser-document","situation":"Dans « Terre des hommes », chaque compagnon de Saint-Exupéry a son épisode. Retrouve-les, puis suis l’accident de Libye.","documents":[{"id":"epis","type":"tableau","titre":"Les épisodes du livre","colonnes":["Personnage","Épisode"],"lignes":[["Mermoz","Disparu en mer"],["Guillaumet","?"],["Prévot","Compagnon de l’accident de Libye, 1935"]],"enteteLignes":true},{"id":"libye","type":"chaine","titre":"L’accident de Libye","disposition":"colonne","noeuds":[{"id":"z1","texte":"Crash dans le désert de Libye, en 1935"},{"id":"z2","texte":"Saint-Exupéry et Prévot errent, assoiffés"},{"id":"z3","texte":"?"},{"id":"z4","texte":"Retour à la vie"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"}]}],"questions":[{"enonce":"Touche la case qui dit ce qui est arrivé à Mermoz.","aide":"Regarde la ligne de Mermoz.","type":"zone","document":"epis","multiple":false},{"enonce":"Que raconte la case « ? » sur Guillaumet ?","aide":"Pense à ce qui se passe dans les montagnes, après un crash.","type":"choix","options":[{"id":"a","texte":"Il guide les caravanes du Sahara"},{"id":"b","texte":"Il traverse l’Atlantique en hydravion"},{"id":"c","texte":"Il marche cinq jours dans les Andes"},{"id":"d","texte":"Il est chef d’escale au cap Juby"}],"multiple":false},{"enonce":"Complète l’épisode de Libye (la case « ? » de la chaîne).","aide":"Le sauveur est un homme du désert.","type":"trous","segments":["Un ",0," anonyme sauve les deux hommes perdus dans le ",1,"."],"banque":["Bédouin","désert","port","marchand"]},{"enonce":"Relie chaque figure du livre à ce qu’elle incarne.","aide":"Chaque épisode du tableau et de la chaîne t’aide.","type":"association","gauche":[{"id":"g0","texte":"Guillaumet"},{"id":"g1","texte":"Mermoz"},{"id":"g2","texte":"Prévot"},{"id":"g3","texte":"Le Bédouin"}],"droite":[{"id":"d0","texte":"Le pionnier des lignes"},{"id":"d1","texte":"Le courage obstiné, l’ami"},{"id":"d2","texte":"Le sauveur anonyme"},{"id":"d3","texte":"Le mécanicien, compagnon du crash"}]}]}$ex$::jsonb,
