  ('b7794612-272b-56ce-a14b-133150a6d4ad'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Responsable de sa vis","competence":"argumenter","situation":"Samir et Chloé discutent de ce qu’est l’avion pour Saint-Exupéry. Un court passage, écrit pour l’exercice à la manière de l’auteur, éclaire leur débat.","documents":[{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Samir","emoji":"👦","cote":"gauche"},{"nom":"Chloé","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Samir","texte":"Pour Saint-Exupéry, l’avion est une machine à voler, c’est tout."},{"qui":"Chloé","texte":"Non : c’est un outil qui révèle la terre et les hommes."},{"qui":"Samir","texte":"Alors le métier compterait plus que la machine ?"},{"qui":"Chloé","texte":"Il donne un sens. Et il apprend la responsabilité."}]},{"id":"pas","type":"texte","genre":"recit","titre":"Un passage à la manière de Saint-Exupéry","blocs":["Au poste de nuit, le mécanicien resserre une dernière vis. Personne ne dira que cette vis a sauvé le courrier. Pourtant, sans elle, le moteur se serait tu au-dessus de la montagne. Celui qui répond de sa vis répond du courrier ; celui qui répond du courrier répond des hommes qui l’attendent. Ainsi le métier fait des responsables avant de faire des héros."],"source":"Texte écrit pour l’exercice, à la manière de Saint-Exupéry"}],"questions":[{"enonce":"Touche le mot du passage que Chloé met elle aussi en avant.","aide":"C’est le mot qui termine la dernière réplique de Chloé, sous une autre forme.","type":"zone","document":"pas","multiple":false},{"enonce":"Quelle réplique le passage et le cours soutiennent-ils ?","aide":"Dans le passage, d’où vient la valeur de la vis resserrée ?","type":"choix","options":[{"id":"a","texte":"Chloé : le pilote n’est responsable que de lui-même"},{"id":"b","texte":"Samir : l’avion est seulement une machine à voler"},{"id":"c","texte":"Samir : le métier compte moins que la machine"},{"id":"d","texte":"Chloé : l’avion est un outil qui révèle la terre et les hommes"}],"multiple":false},{"enonce":"Relie chaque idée du livre à ce qu’elle dit.","aide":"Ce sont les trois idées du propos de « Terre des hommes ».","type":"association","gauche":[{"id":"g0","texte":"Le métier"},{"id":"g1","texte":"La responsabilité"},{"id":"g2","texte":"Le lien entre camarades"}],"droite":[{"id":"d0","texte":"Elle définit l’adulte"},{"id":"d1","texte":"Il vaut mieux que tout discours"},{"id":"d2","texte":"Il donne un sens"}]},{"enonce":"Dans quel genre peut-on ranger « Terre des hommes » à l’oral ?","aide":"Le livre n’est ni un roman ni de la fiction pure.","type":"choix","options":[{"id":"a","texte":"Entre l’essai, le récit et l’autobiographie"},{"id":"b","texte":"Un recueil de poèmes en prose"},{"id":"c","texte":"Un roman policier en plusieurs tomes"},{"id":"d","texte":"Une pièce de théâtre en trois actes"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m57"]},"explication":"Le passage se clôt sur les **responsables** : la responsabilité est ce que le métier apprend."},{"cle":{"type":"choix","ids":["d"]},"explication":"La vis compte parce qu’elle engage le courrier et les hommes : la machine est un **outil qui révèle la terre et les hommes**, comme le dit Chloé."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"Le **métier** donne un sens, la **responsabilité** définit l’adulte, le **lien entre camarades** vaut mieux que tout discours : « Être homme, c’est précisément être responsable. »"},{"cle":{"type":"choix","ids":["a"]},"explication":"Le livre se tient **à la frontière de l’essai, du récit et de l’autobiographie** : c’est ce qui fait son intérêt pour une dissertation sur l’humanisme."}]$ex$::jsonb),
