   $ex${"titre":"Des tempéraments étudiés comme des corps","competence":"argumenter","situation":"Eva et Tom ne lisent pas le remords des amants de la même façon. La préface de Zola les départage.","documents":[{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Eva","emoji":"👧","cote":"gauche"},{"nom":"Tom","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Eva","texte":"Après le crime, leur remords est moral : ils comprennent qu’ils ont mal agi."},{"qui":"Tom","texte":"Non. Ce qui les ronge, c’est le corps : leurs nerfs et leur sang."},{"qui":"Eva","texte":"Alors ce ne sont plus des personnages libres ?"},{"qui":"Tom","texte":"Zola le dit : ce sont des tempéraments, pas des caractères."}]},{"id":"pre","type":"texte","genre":"source","titre":"Extrait de la préface","blocs":["« J’ai choisi des personnages souverainement dominés par leurs nerfs et leur sang… j’ai simplement fait sur deux corps vivants le travail analytique que les chirurgiens font sur des cadavres. »"],"source":"Émile Zola, préface de la seconde édition de *Thérèse Raquin* (extrait donné par le cours)"}],"questions":[{"enonce":"Touche les deux mots de la préface qui dominent les personnages.","aide":"Ce sont les deux éléments du corps qui commandent leurs actes.","type":"zone","document":"pre","multiple":true},{"enonce":"Touche le mot qui compare l’écriture de Zola au travail des chirurgiens.","aide":"Les chirurgiens étudient un corps sans vie.","type":"zone","document":"pre","multiple":false},{"enonce":"Quelle réplique la préface confirme-t-elle ?","aide":"Que dominent les nerfs et le sang ?","type":"choix","options":[{"id":"a","texte":"Tom : Zola refuse toute démarche scientifique"},{"id":"b","texte":"Tom : le remords des personnages est physique, non moral"},{"id":"c","texte":"Eva : le remords des personnages est moral"},{"id":"d","texte":"Eva : les personnages sont libres de leurs actes"}],"multiple":false},{"enonce":"Relie chaque personnage à son tempérament.","aide":"Le cours donne le tempérament de chaque personnage.","type":"association","gauche":[{"id":"g0","texte":"Thérèse"},{"id":"g1","texte":"Laurent"},{"id":"g2","texte":"Camille"},{"id":"g3","texte":"Madame Raquin"}],"droite":[{"id":"d0","texte":"Mère aimante, puis témoin impuissant"},{"id":"d1","texte":"Maladif, égoïste"},{"id":"d2","texte":"Sanguin, paresseux, peintre raté"},{"id":"d3","texte":"Nerveuse, passionnée, longtemps contenue"}]},{"enonce":"Que peint Laurent après le crime ?","aide":"Ses tableaux ne lui échappent plus.","type":"choix","options":[{"id":"a","texte":"Des natures mortes, comme avant le crime"},{"id":"b","texte":"Un grand portrait officiel de Camille"},{"id":"c","texte":"Des visages qui ressemblent tous au noyé"},{"id":"d","texte":"Des paysages ensoleillés de bord de Seine"}],"multiple":false}]}$ex$::jsonb,
