   $ex${"titre":"Jouer pour qui ?","competence":"argumenter","situation":"Camille et Nabil débattent de la raison pour laquelle Sainte Colombe joue. Un passage écrit pour l’exercice, à la manière de Quignard, nourrit leur discussion.","documents":[{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Camille","emoji":"👧","cote":"gauche"},{"nom":"Nabil","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Camille","texte":"Sainte Colombe joue pour devenir célèbre, comme Marais."},{"qui":"Nabil","texte":"Il joue pour sa femme morte, pas pour la gloire."},{"qui":"Camille","texte":"Mais elle est morte : qui l’entend ?"},{"qui":"Nabil","texte":"La musique est faite pour atteindre les morts."}]},{"id":"pas","type":"texte","genre":"recit","titre":"Un passage à la manière de Quignard","blocs":["Il jouait. La cabane était froide. La viole chantait à voix basse pour une morte qui ne répondait pas. Quand l’archet se taisait, il écoutait le silence qui venait après. Il n’avait besoin d’aucun public."],"source":"Texte écrit pour l’exercice, à la manière de Pascal Quignard"}],"questions":[{"enonce":"Touche le mot qui dit pour qui Sainte Colombe joue.","aide":"C’est le mot que Nabil emploie dans sa première réplique, sous une autre forme.","type":"zone","document":"pas","multiple":false},{"enonce":"Quelle réplique le passage soutient-il ?","aide":"Le passage dit qu’il n’a besoin d’aucun public.","type":"choix","options":[{"id":"a","texte":"Camille : il joue pour devenir célèbre"},{"id":"b","texte":"Camille : il joue pour un public nombreux"},{"id":"c","texte":"Nabil : il joue pour distraire les gens de la cour"},{"id":"d","texte":"Nabil : il joue pour sa femme morte, pas pour la gloire"}],"multiple":false},{"enonce":"Relie chaque trait d’écriture du passage à son effet.","aide":"Compare la forme des phrases, puis ce qu’elles disent.","type":"association","gauche":[{"id":"g0","texte":"Des phrases courtes et sèches"},{"id":"g1","texte":"Un seul auditeur, la morte"},{"id":"g2","texte":"Aucun public, aucune cour"}],"droite":[{"id":"d0","texte":"Une écriture sans effets"},{"id":"d1","texte":"Le refus du succès"},{"id":"d2","texte":"Une musique faite pour atteindre les morts"}]},{"enonce":"Range chaque élément : musique de cour ou musique vraie ?","aide":"La première cherche le succès, la seconde le silence et la mémoire.","type":"categories","categories":[{"id":"c0","texte":"Musique de cour"},{"id":"c1","texte":"Musique vraie"}],"items":[{"id":"i0","texte":"Atteindre les morts"},{"id":"i1","texte":"Dire ce que les mots ne disent pas"},{"id":"i2","texte":"Gagner de l’argent et la célébrité"},{"id":"i3","texte":"Plaire au roi"}]}]}$ex$::jsonb,
