  ('3163cb72-edfc-5f22-a1b1-5f57032b2dac'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Un innocent roué vif","competence":"analyser-texte","situation":"Voici un résumé de l’affaire Calas, non chronologique. Retrouve les mots clés, remets les événements en ordre et reconnais les acteurs.","documents":[{"id":"res","type":"texte","genre":"article","titre":"Résumé de l’affaire","blocs":["Le *Traité* naît d’une affaire toulousaine. Quand le jugement est cassé, en 1765, Calas est réhabilité, trois ans après sa mort. Tout avait commencé en 1761 : le fils d’un marchand protestant est retrouvé pendu, et la rumeur accuse le père de l’avoir tué pour l’empêcher de se convertir. Sans preuve, sur la seule clameur publique, les juges condamnent Jean Calas : il est roué vif en mars 1762."],"source":"Résumé écrit pour l’exercice"}],"questions":[{"enonce":"Touche les deux mots qui disent sur quoi repose la condamnation.","aide":"Il n’y a aucune preuve : que reste-t-il ?","type":"zone","document":"res","multiple":true},{"enonce":"Remets les événements dans l’ordre où ils se produisent.","aide":"Le texte commence par la fin : relis-le en cherchant les dates.","type":"ordre","items":[{"id":"a","texte":"Le jugement est cassé"},{"id":"b","texte":"Le fils Marc-Antoine est retrouvé pendu"},{"id":"c","texte":"Le père est accusé de l’avoir tué"},{"id":"d","texte":"Jean Calas est roué vif"}]},{"enonce":"Pourquoi la famille Calas est-elle soupçonnée ?","aide":"Pour la rumeur, le père voulait empêcher son fils de se convertir.","type":"choix","options":[{"id":"a","texte":"Elle est étrangère : on la soupçonne d’espionnage"},{"id":"b","texte":"Elle est protestante : la rumeur y voit un mobile religieux"},{"id":"c","texte":"Elle est riche : on veut s’emparer de ses biens"},{"id":"d","texte":"Elle est noble : on veut abaisser sa maison"}],"multiple":false},{"enonce":"Relie chaque figure à son rôle dans l’affaire.","aide":"Pense à ce que chacun subit ou fait.","type":"association","gauche":[{"id":"g0","texte":"Jean Calas"},{"id":"g1","texte":"Marc-Antoine"},{"id":"g2","texte":"Les juges de Toulouse"},{"id":"g3","texte":"Voltaire"}],"droite":[{"id":"d0","texte":"Le fils retrouvé mort"},{"id":"d1","texte":"L’avocat de l’opinion"},{"id":"d2","texte":"Le fanatisme au pouvoir"},{"id":"d3","texte":"Le marchand protestant, victime d’une erreur judiciaire"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m57","m58"]},"explication":"Les juges se fondent sur la seule **clameur publique**, sans preuve."},{"cle":{"type":"ordre","ids":["b","c","d","a"]},"explication":"L’affaire commence par la **mort du fils**, puis l’**accusation du père**, l’**exécution** (mars 1762) et la **cassation** (1765)."},{"cle":{"type":"choix","ids":["b"]},"explication":"La famille est **protestante** : on accuse le père d’avoir tué son fils pour l’empêcher de se convertir au catholicisme."},{"cle":{"type":"association","paires":{"g1":"d0","g3":"d1","g2":"d2","g0":"d3"}},"explication":"**Calas** est la victime, **Marc-Antoine** le fils retrouvé mort, les **juges** incarnent le fanatisme, **Voltaire** défend l’innocent devant l’opinion."}]$ex$::jsonb),
