   $ex${"titre":"Tolérer, ce n’est pas supprimer","competence":"argumenter","situation":"Jade et Karim discutent de ce que veut Voltaire. La Prière à Dieu, qui clôt le livre, tranche.","documents":[{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Jade","emoji":"👧","cote":"gauche"},{"nom":"Karim","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Jade","texte":"Voltaire veut supprimer toute religion."},{"qui":"Karim","texte":"Non : il veut que les différences de croyance ne servent plus à haïr."},{"qui":"Jade","texte":"Mais il écrit « Écrasons l’infâme » !"},{"qui":"Karim","texte":"Il vise le fanatisme, pas la foi."}]},{"id":"pri","type":"texte","genre":"source","titre":"La Prière à Dieu","blocs":["« Fais que les petites différences entre les vêtements qui couvrent nos débiles corps… ne soient pas des signaux de haine et de persécution. »"],"source":"Voltaire, *Traité sur la tolérance* (1763), « Prière à Dieu » — extrait donné par le cours"}],"questions":[{"enonce":"Touche les deux mots qui disent ce que les différences ne doivent pas provoquer.","aide":"Ce sont deux noms, à la fin de la phrase.","type":"zone","document":"pri","multiple":true},{"enonce":"Quelle réplique la Prière confirme-t-elle ?","aide":"La prière parle de différences, pas de suppression.","type":"choix","options":[{"id":"a","texte":"Jade : Voltaire veut supprimer toute religion"},{"id":"b","texte":"Karim : Voltaire combat le fanatisme, non la religion"},{"id":"c","texte":"Jade : Voltaire souhaite des signaux de reconnaissance"},{"id":"d","texte":"Karim : Voltaire excuse les persécutions religieuses"}],"multiple":false},{"enonce":"Range chaque élément : ce que Voltaire dénonce ou ce qu’il défend.","aide":"Pense à l’affaire Calas, puis à ce que le livre réclame.","type":"categories","categories":[{"id":"c0","texte":"Ce qu’il dénonce"},{"id":"c1","texte":"Ce qu’il défend"}],"items":[{"id":"i0","texte":"La raison"},{"id":"i1","texte":"Une condamnation sans preuve"},{"id":"i2","texte":"Le fanatisme"},{"id":"i3","texte":"La justice"},{"id":"i4","texte":"La liberté de conscience"}]},{"enonce":"Complète ce que le livre mêle.","aide":"Un procédé qui dit le contraire de ce qu’on pense ; un homme de lettres qui prend une cause.","type":"trous","segments":["Le livre mêle récit, argumentation et ",0," ; Voltaire y invente le rôle de l’",1,"."],"banque":["intellectuel","ironie","historien","poésie"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m19","m22"]},"explication":"Les différences ne doivent pas devenir des signaux de **haine** et de **persécution**."},{"cle":{"type":"choix","ids":["b"]},"explication":"La Prière demande que les différences ne servent pas à **persécuter** : Voltaire combat le **fanatisme**, non la religion."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c1","i4":"c1"}},"explication":"Voltaire **dénonce** le fanatisme et la condamnation sans preuve ; il **défend** la liberté de conscience, la justice et la raison."},{"cle":{"type":"trous","trous":[["ironie"],["intellectuel"]]},"affichage":"ironie · intellectuel","explication":"Le livre mêle **récit**, **argumentation** et **ironie** ; Voltaire y invente le rôle de l’**intellectuel** qui universalise une cause."}]$ex$::jsonb),
  ('d72b5737-9f8f-5383-8aa5-b50395cded77'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Qui est qui dans la légende ?","competence":"analyser-document","situation":"Tu prépares l’oral sur « Tristan et Iseult ». Identifie les personnages, puis la façon dont la légende nous est parvenue.","documents":[{"id":"pers","type":"tableau","titre":"Les personnages","colonnes":["Personnage","Son rôle"],"lignes":[["Tristan","Le chevalier, neveu du roi Marc"],["Iseult la Blonde","La reine, guérisseuse"],["Le roi Marc","?"],["Brangien","La servante, responsable du philtre"]],"enteteLignes":true},{"id":"trans","type":"texte","genre":"article","titre":"Comment la légende nous est parvenue","blocs":["Il n’existe pas un seul *Tristan*, mais des versions fragmentaires du XIIe siècle. Béroul et Thomas d’Angleterre écrivent en français ; Gottfried de Strasbourg écrit en allemand ; Marie de France compose, en français, le *Lai du chèvrefeuille*. Le texte qu’on lit aujourd’hui est le plus souvent la reconstitution de Joseph Bédier, en 1900."],"source":"Résumé écrit pour l’exercice"}],"questions":[{"enonce":"Touche la case qui dit qui est responsable du philtre.","aide":"Cherche la servante d’Iseult.","type":"zone","document":"pers","multiple":false},{"enonce":"Que faut-il écrire à la place de la case « ? » ?","aide":"Il est le mari promis d’Iseult la Blonde, et l’oncle de Tristan.","type":"choix","options":[{"id":"a","texte":"L’oncle trahi, partagé entre colère et tendresse"},{"id":"b","texte":"La femme que Tristan épouse loin d’Iseult"},{"id":"c","texte":"Le nain qui guette les amants à la cour"},{"id":"d","texte":"Le chevalier qui vainc le Morholt d’Irlande"}],"multiple":false},{"enonce":"Range chaque auteur selon la langue de sa version.","aide":"Une seule version est allemande.","type":"categories","categories":[{"id":"c0","texte":"Écrit en français"},{"id":"c1","texte":"Écrit en allemand"}],"items":[{"id":"i0","texte":"Gottfried de Strasbourg"},{"id":"i1","texte":"Thomas d’Angleterre"},{"id":"i2","texte":"Béroul"},{"id":"i3","texte":"Marie de France (Lai du chèvrefeuille)"}]},{"enonce":"Complète ce que dit le texte de la version que l’on lit.","aide":"Cherche le dernier nom propre du texte.","type":"trous","segments":["Le texte le plus souvent lu est la reconstitution de Joseph ",0,", en ",1,"."],"banque":["1578","1900","Bédier","Béroul"]}]}$ex$::jsonb,
