   $ex${"titre":"Quand il ne se passe rien","competence":"argumenter","situation":"Paul et Lou lisent le même court passage, écrit pour l’exercice à la manière de Sarraute, et ne s’accordent pas.","documents":[{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Paul","emoji":"👦","cote":"gauche"},{"nom":"Lou","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Paul","texte":"Il ne se passe rien dans ce texte : il est vide."},{"qui":"Lou","texte":"Au contraire : tout se passe sous la conversation, c’est un tropisme."},{"qui":"Paul","texte":"Mais personne ne dit rien de grave."},{"qui":"Lou","texte":"C’est justement ce qu’on ne dit pas qui bouge."}]},{"id":"pas","type":"texte","genre":"recit","titre":"Un passage à la manière de Sarraute","blocs":["Ils s’étaient assis autour de la table, et elle souriait. Quelque chose avait glissé, presque rien, un mot de trop dit sur un ton léger, et sous la phrase aimable quelque chose de tiède et de visqueux s’était mis à remuer, comme un insecte qu’on frôle. Elle continuait à sourire. On parlait de la pluie."],"source":"Texte écrit pour l’exercice, à la manière de Nathalie Sarraute"}],"questions":[{"enonce":"Touche l’image concrète qui rend sensible le mouvement intérieur.","aide":"C’est une comparaison avec un petit animal.","type":"zone","document":"pas","multiple":false},{"enonce":"Range chaque élément : ce qu’on dit, ou ce qui se passe dessous ?","aide":"La conversation est ce qu’on voit ; le tropisme est ce qui glisse en dessous.","type":"categories","categories":[{"id":"c0","texte":"La conversation"},{"id":"c1","texte":"Le tropisme"}],"items":[{"id":"i0","texte":"Quelque chose de tiède et de visqueux se met à remuer"},{"id":"i1","texte":"Elle continuait à sourire"},{"id":"i2","texte":"On parlait de la pluie"},{"id":"i3","texte":"Quelque chose avait glissé, presque rien"}]},{"enonce":"Quelle réplique le passage soutient-il ?","aide":"Que se passe-t-il sous la phrase aimable ?","type":"choix","options":[{"id":"a","texte":"Paul : la scène raconte un crime à demi-mot"},{"id":"b","texte":"Lou : le texte décrit un voyage en train"},{"id":"c","texte":"Paul : le texte ne raconte rien et n’a aucun sens"},{"id":"d","texte":"Lou : tout se passe sous la conversation"}],"multiple":false},{"enonce":"Relie chaque procédé du passage à son effet.","aide":"Pense à ce que chaque procédé fait ressentir.","type":"association","gauche":[{"id":"g0","texte":"Une image d’insecte"},{"id":"g1","texte":"L’imparfait (« souriait », « continuait »)"},{"id":"g2","texte":"« Ils », « elle », « on »"}],"droite":[{"id":"d0","texte":"Une scène sans début ni fin"},{"id":"d1","texte":"Rendre sensible l’impalpable"},{"id":"d2","texte":"Le refus du personnage classique"}]}]}$ex$::jsonb,
