   $ex${"titre":"Héroïque et vaine","competence":"argumenter","situation":"Maé et Théo jugent la mère différemment. Un passage écrit pour l’exercice, à la manière de Duras, les aide à trancher.","documents":[{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Maé","emoji":"👧","cote":"gauche"},{"nom":"Théo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Maé","texte":"La mère est ridicule : elle s’entête à lutter contre la mer."},{"qui":"Théo","texte":"Elle est tragique : sa lutte est héroïque et vaine."},{"qui":"Maé","texte":"Vaine, donc inutile."},{"qui":"Théo","texte":"Inutile, mais pas ridicule : elle ne se résigne pas."}]},{"id":"pas","type":"texte","genre":"recit","titre":"Un passage à la manière de Duras","blocs":["La mère regarde la mer. La mer monte. Elle avait cru qu’on pouvait arrêter l’eau avec des troncs et du courage. La mer est revenue la nuit, comme chaque année. La mère ne dit rien. Elle regarde encore."],"source":"Texte écrit pour l’exercice, à la manière de Marguerite Duras"}],"questions":[{"enonce":"Touche les deux mots qui disent les moyens dont dispose la mère.","aide":"L’un est un matériau, l’autre une qualité morale.","type":"zone","document":"pas","multiple":true},{"enonce":"Relie chaque procédé du passage à son effet.","aide":"Pense à ce que chaque détail fait ressentir.","type":"association","gauche":[{"id":"g0","texte":"La répétition du mot « mer »"},{"id":"g1","texte":"Le silence de la mère"},{"id":"g2","texte":"Les troncs contre l’eau"}],"droite":[{"id":"d0","texte":"Une lutte héroïque et vaine"},{"id":"d1","texte":"Le ressassement qui tend l’écriture"},{"id":"d2","texte":"Une lutte vaine, sans plainte"}]},{"enonce":"Quelle réplique le passage confirme-t-il ?","aide":"La mère revient chaque année, la mer aussi.","type":"choix","options":[{"id":"a","texte":"Maé : la mère gagne et arrête la mer"},{"id":"b","texte":"Maé : sa lutte est ridicule et comique"},{"id":"c","texte":"Théo : la mère renonce dès le premier jour"},{"id":"d","texte":"Théo : sa lutte est tragique, héroïque et vaine"}],"multiple":false},{"enonce":"Range chaque élément : héroïque ou vain ?","aide":"Ce que fait la mère est héroïque ; ce que fait la mer rend tout inutile.","type":"categories","categories":[{"id":"c0","texte":"Héroïque"},{"id":"c1","texte":"Vain"}],"items":[{"id":"i0","texte":"La mère construit des barrages avec les paysans"},{"id":"i1","texte":"Elle refuse de se résigner"},{"id":"i2","texte":"La mer envahit la concession chaque année"},{"id":"i3","texte":"La mer emporte les barrages"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m19","m22"]},"explication":"La mère n’a que des **troncs** et du **courage** face à la mer."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"La **répétition** donne le ressassement ; le **silence** dit une lutte sans plainte ; les **troncs** face à l’eau, une lutte héroïque et vaine."},{"cle":{"type":"choix","ids":["d"]},"explication":"La mère s’obstine avec ses troncs et son courage, et la mer revient : sa lutte est **héroïque et vaine**, comme le dit Théo."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1"}},"explication":"Ce que **la mère** fait est héroïque ; ce que **la mer** fait rend tout vain."}]$ex$::jsonb),
  ('e54a6c3e-daae-5016-b229-89748abdc6fe'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le seul livre que Rimbaud ait publié","competence":"se-reperer-temps","situation":"Tu prépares une fiche sur Une saison en enfer. Place le livre dans la vie de Rimbaud, puis recopie sa carte d’identité.","documents":[{"id":"frise","type":"frise","titre":"Rimbaud et son livre","debut":1850,"fin":1895,"pas":5,"evenements":[{"id":"z1","date":1854,"nom":"Naissance"},{"id":"z2","date":1873,"nom":"Une saison en enfer"},{"id":"z3","date":1886,"nom":"Illuminations"},{"id":"z4","date":1891,"nom":"Mort"}]},{"id":"carte","type":"fiche","modele":"affiche","entete":"Une saison en enfer","sousTitre":"Arthur Rimbaud","emoji":"🔥","lignes":[{"texte":"Écrit","valeur":"D’avril à août 1873"},{"texte":"Âge de l’auteur","valeur":"Dix-huit ans"},{"texte":"Forme","valeur":"Neuf sections en prose"},{"texte":"Publication","valeur":"À compte d’auteur, à Bruxelles"}],"pied":"Le seul livre que Rimbaud ait mené lui-même à la publication","teinte":"violet"}],"questions":[{"enonce":"Sur la frise, touche l’événement qui correspond à la parution du livre.","aide":"Le livre est écrit et publié la même année.","type":"zone","document":"frise","multiple":false},{"enonce":"Rimbaud est né en 1854 et mort en 1891. Combien d’années a-t-il vécu ?","aide":"Soustrais les deux dates de la frise.","type":"nombre","unite":"ans"},{"enonce":"Complète la phrase avec la carte du livre.","aide":"Tout est dans la fiche du livre.","type":"trous","segments":["Le livre est écrit à ",0," ans, publié à compte d’",1," et composé de neuf sections en ",2,"."],"banque":["vingt-cinq","vers","auteur","prose","éditeur","dix-huit"]}]}$ex$::jsonb,
