  ('e54a6c3e-daae-5016-b229-89748abdc6fe'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les sections d’un bilan","competence":"analyser-texte","situation":"Pour ton oral, tu dois savoir ce que contient chaque section de Une saison en enfer. Le tableau est en désordre : remets-le d’aplomb.","documents":[{"id":"sections","type":"tableau","titre":"Les sections du livre (en désordre)","colonnes":["Section","Ce qu’elle contient"],"lignes":[["Adieu","La sortie"],["Délires II : Alchimie du verbe","?"],["Mauvais sang","L’origine, la race, la révolte"],["Délires I : Vierge folle, l’Époux infernal","La vie commune avec Verlaine, du point de vue de l’autre"],["Nuit de l’enfer","La crise"]],"enteteLignes":true},{"id":"alch","type":"texte","genre":"recit","titre":"Dans « Alchimie du verbe »","blocs":["« Je m’habituai à l’hallucination simple… puis j’expliquai mes sophismes magiques avec l’hallucination des mots. »"],"source":"Arthur Rimbaud, *Une saison en enfer* (1873), « Alchimie du verbe » (citation abrégée)"}],"questions":[{"enonce":"Remets les cinq sections du tableau dans l’ordre où on les lit.","aide":"Le livre part de l’origine et de la révolte, et finit par la sortie.","type":"ordre","items":[{"id":"a","texte":"Délires II"},{"id":"b","texte":"Délires I"},{"id":"c","texte":"Adieu"},{"id":"d","texte":"Nuit de l’enfer"},{"id":"e","texte":"Mauvais sang"}]},{"enonce":"Que contient la section « Alchimie du verbe » (la case « ? ») ?","aide":"Le titre parle d’une « alchimie » : de quoi Rimbaud fait-il le bilan ?","type":"choix","options":[{"id":"a","texte":"Rimbaud raconte et juge sa propre entreprise poétique"},{"id":"b","texte":"Le récit de ses départs vers Chypre et l’Abyssinie"},{"id":"c","texte":"La vie commune avec Verlaine racontée par l’autre"},{"id":"d","texte":"Un hymne à l’origine et à la race de l’auteur"}],"multiple":false},{"enonce":"Touche le mot qui qualifie la première hallucination, celle des débuts.","aide":"Elle vient avant les « sophismes magiques » : c’est la plus modeste.","type":"zone","document":"alch","multiple":false},{"enonce":"Relie chaque titre de Rimbaud au fait qui lui correspond.","aide":"Chaque titre est une étape du parcours de Rimbaud.","type":"association","gauche":[{"id":"g0","texte":"Lettre du voyant"},{"id":"g1","texte":"Une saison en enfer"},{"id":"g2","texte":"Illuminations"},{"id":"g3","texte":"Le Bateau ivre"}],"droite":[{"id":"d0","texte":"Elle réclame un « dérèglement de tous les sens »"},{"id":"d1","texte":"Poème écrit en 1871"},{"id":"d2","texte":"Publiées par Verlaine en 1886"},{"id":"d3","texte":"Le seul livre que Rimbaud ait publié lui-même"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"ordre","ids":["e","d","b","a","c"]},"explication":"On lit **Mauvais sang**, **Nuit de l’enfer**, **Délires I**, **Délires II**, puis **Adieu**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Dans « Alchimie du verbe », Rimbaud **raconte et juge sa propre entreprise poétique**, en citant même ses anciens poèmes."},{"cle":{"type":"zone","ids":["m6"]},"explication":"L’hallucination est d’abord **simple**, puis elle devient celle des mots : le poète décrit l’escalade de sa méthode."},{"cle":{"type":"association","paires":{"g0":"d0","g3":"d1","g2":"d2","g1":"d3"}},"explication":"La **Lettre du voyant** fixe le programme, **Le Bateau ivre** le met en images, **Une saison en enfer** en fait le bilan, les **Illuminations** le prolongent."}]$ex$::jsonb),
  ('e54a6c3e-daae-5016-b229-89748abdc6fe'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Bilan ou triomphe ?","competence":"argumenter","situation":"Deux élèves se disputent sur le sens du livre : une réussite, ou le constat d’un échec ? Tranche avec le dialogue et les mots de Rimbaud.","documents":[{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Léa","emoji":"👧","cote":"gauche"},{"nom":"Yanis","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Léa","texte":"Le livre est un triomphe : Rimbaud y a enfin trouvé la langue nouvelle qu’il cherchait."},{"qui":"Yanis","texte":"Pas du tout : il récapitule son projet de voyant et il en montre l’échec."},{"qui":"Léa","texte":"Pourtant il écrit qu’il faut être absolument moderne !"},{"qui":"Yanis","texte":"Oui, mais c’est un bilan, et une rupture : après, il cessera d’écrire."}]},{"id":"fin","type":"texte","genre":"recit","titre":"Des mots de la conclusion","blocs":["« Il faut être absolument moderne. »","« … et il me sera loisible de posséder la vérité dans une âme et un corps. »"],"source":"Arthur Rimbaud, *Une saison en enfer* (1873), « Adieu »"}],"questions":[{"enonce":"Touche le mot de Yanis qui dit ce que le livre montre du projet de voyant.","aide":"Yanis contredit Léa : le projet ne réussit pas.","type":"zone","document":"deb","multiple":false},{"enonce":"Quelle lecture du livre le dialogue et le cours soutiennent-ils ?","aide":"Reprends les derniers mots de la réplique de Yanis.","type":"choix","options":[{"id":"a","texte":"Un manifeste joyeux qui annonce de nouveaux recueils de vers"},{"id":"b","texte":"Un bilan qui récapitule le projet de voyant et en montre l’échec"},{"id":"c","texte":"Le récit chronologique de l’enfance à Charleville"},{"id":"d","texte":"Une suite de poèmes en vers libres consacrés à un voyage"}],"multiple":false},{"enonce":"Touche le mot qui nomme ce que Rimbaud espère posséder dans une âme et un corps.","aide":"C’est ce que cherche tout voyant.","type":"zone","document":"fin","multiple":false},{"enonce":"Range chaque fait : appartient-il au bilan que fait le livre, ou à la rupture qui le suit ?","aide":"Demande-toi : regarde-t-il en arrière ou tourne-t-il la page ?","type":"categories","categories":[{"id":"c0","texte":"Le bilan"},{"id":"c1","texte":"La rupture"}],"items":[{"id":"i0","texte":"Il cesse peu à peu d’écrire"},{"id":"i1","texte":"Il récapitule son projet de voyant"},{"id":"i2","texte":"« Alchimie du verbe » juge ses propres poèmes"},{"id":"i3","texte":"Il part à l’étranger : Chypre, l’Abyssinie"}]},{"enonce":"Relie chaque procédé du livre à ce qu’il fait.","aide":"Pense à ce que fait Rimbaud de ses propres poèmes dans le livre.","type":"association","gauche":[{"id":"g0","texte":"La prose poétique"},{"id":"g1","texte":"Les citations de ses poèmes dans « Alchimie du verbe »"},{"id":"g2","texte":"Les Illuminations de 1886"}],"droite":[{"id":"d0","texte":"Elles prolongent la recherche du livre"},{"id":"d1","texte":"Elle donne des rythmes brisés, des exclamations, des formules"},{"id":"d2","texte":"Elles permettent à l’auteur de les juger"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m30"]},"explication":"Le livre montre l’**échec** du projet de voyant : c’est un bilan, pas un triomphe."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le livre est un **bilan et une rupture** : Rimbaud récapitule sa recherche, en constate l’échec, puis cesse d’écrire."},{"cle":{"type":"zone","ids":["m13"]},"explication":"Il espère posséder la **vérité** : c’est la dernière ambition du livre, au moment de l’adieu."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c1"}},"explication":"Le **bilan** passe en revue le projet et les poèmes ; la **rupture**, c’est le silence poétique et les départs qui suivent."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"La **prose poétique** casse le rythme ; la **citation** sert à **juger** ; les **Illuminations** prolongent la recherche."}]$ex$::jsonb),
