  ('0211939c-07a4-5c00-ae9c-3bdd17389725'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Jeanne n’est pas Emma","competence":"argumenter","situation":"Une élève rapproche Jeanne d’Emma Bovary ; son camarade proteste. Lis le dialogue et la dernière phrase du roman, puis construis ton argument.","documents":[{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Inès","emoji":"👧","cote":"gauche"},{"nom":"Tom","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Inès","texte":"Jeanne, c’est Emma Bovary version province : elle finit par se révolter."},{"qui":"Tom","texte":"Non : Jeanne ne se révolte jamais, c’est justement ce qui la distingue."},{"qui":"Inès","texte":"Alors il ne se passe rien dans ce roman ?"},{"qui":"Tom","texte":"Si, mais rien d’extraordinaire : la vie use une femme qui n’a rien fait de mal."}]},{"id":"fin","type":"texte","genre":"recit","titre":"La dernière phrase du roman","blocs":["« La vie, voyez-vous, ça n’est jamais si bon ni si mauvais qu’on croit. »"],"source":"Guy de Maupassant, *Une vie* (1883), dernière phrase"},{"id":"these","type":"tableau","titre":"Un argument à compléter","colonnes":["Thèse","Argument","Exemple"],"lignes":[["Le roman est réaliste","Il peint la vie ordinaire, sans héros ni aventures","?"],["C’est le roman du désenchantement","La vie use peu à peu une femme sans faute","Julien trompe Jeanne, puis Paul la ruine"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le verbe qui sépare Jeanne d’Emma Bovary.","aide":"Tom répond à Inès sur ce que Jeanne ne fait jamais.","type":"zone","document":"deb","multiple":false},{"enonce":"Touche les deux adjectifs que la phrase finale oppose.","aide":"Cherche les deux adjectifs précédés de « si ».","type":"zone","document":"fin","multiple":true},{"enonce":"Que dit cette dernière phrase de la vie ?","aide":"La phrase pèse deux extrêmes l’un contre l’autre.","type":"choix","options":[{"id":"a","texte":"Elle est cruelle pour tous ceux qui acceptent de la subir"},{"id":"b","texte":"Elle est belle pour celles qui se révoltent contre leur sort"},{"id":"c","texte":"Elle récompense à la fin ceux qui savent compter leur argent"},{"id":"d","texte":"Elle n’est ni aussi belle ni aussi cruelle qu’on se l’imagine"}],"multiple":false},{"enonce":"Quel exemple faut-il écrire dans la case « ? » du tableau ?","aide":"Le réalisme peint ce qui est ordinaire.","type":"choix","options":[{"id":"a","texte":"Jeanne dirige seule le domaine avec une grande réussite"},{"id":"b","texte":"Un naufrage sépare Jeanne de ses parents pendant des années"},{"id":"c","texte":"Rien d’extraordinaire n’arrive : la vie quotidienne use Jeanne"},{"id":"d","texte":"Jeanne s’enfuit avec un amant et quitte la Normandie"}],"multiple":false},{"enonce":"Range chaque trait : relève-t-il du roman réaliste, ou du roman d’aventures ?","aide":"Demande-toi si le trait est quotidien ou extraordinaire.","type":"categories","categories":[{"id":"c0","texte":"Roman réaliste (Une vie)"},{"id":"c1","texte":"Roman d’aventures"}],"items":[{"id":"i0","texte":"La lente usure du temps"},{"id":"i1","texte":"Des désillusions quotidiennes"},{"id":"i2","texte":"Des exploits et des évasions spectaculaires"},{"id":"i3","texte":"Une vie ordinaire, sans héros"},{"id":"i4","texte":"Un héros qui triomphe de tous les périls"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m16"]},"explication":"Jeanne ne se **révolte** jamais : elle subit sa vie, là où Emma Bovary la refuse."},{"cle":{"type":"zone","ids":["m8","m11"]},"explication":"La phrase oppose **bon** et **mauvais** pour dire que la vie est un entre-deux."},{"cle":{"type":"choix","ids":["d"]},"explication":"La phrase finale exprime une **résignation lucide** : la vie n’est « jamais si bon ni si mauvais qu’on croit »."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le **réalisme** de Maupassant tient dans l’ordinaire : **rien d’extraordinaire n’arrive**, la vie use simplement Jeanne."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c0","i4":"c1"}},"explication":"Le roman réaliste peint la **vie ordinaire** et son **usure** ; l’aventure vit d’**exploits** et de héros."}]$ex$::jsonb),
