   $ex${"titre":"Un cheval et un chien, un procès","competence":"analyser-texte","situation":"Pour ton oral, tu étudies la page la plus célèbre du conte. Lis la scène écrite pour l’exercice, puis complète le tableau.","documents":[{"id":"scene","type":"texte","genre":"recit","titre":"Dans un bois, près de Babylone","blocs":["Des serviteurs cherchent un cheval et un chien échappés. Zadig, qui passe, les décrit avec précision sans les avoir jamais vus : il a lu les traces dans le sable.","Aussitôt, on l’accuse de les avoir volés."],"source":"Texte écrit pour l’exercice, inspiré d’un épisode de *Zadig* de Voltaire (1748)"},{"id":"episode","type":"tableau","titre":"L’épisode du chien et du cheval","colonnes":["Épisode","Ce qu’il montre"],"lignes":[["Ce que fait Zadig","Il décrit les animaux sans les avoir vus, d’après leurs traces"],["Sa portée","?"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui dit comment Zadig devine les deux animaux.","aide":"Il ne les a pas vus : il lit autre chose.","type":"zone","document":"scene","multiple":false},{"enonce":"Touche le mot qui dit de quoi on accuse Zadig.","aide":"Une accusation à la fin de la scène.","type":"zone","document":"scene","multiple":false},{"enonce":"Que faut-il écrire dans la case « ? » du tableau ?","aide":"Zadig raisonne à partir de traces, comme un enquêteur.","type":"choix","options":[{"id":"a","texte":"Une leçon sur les dangers des voyages en mer"},{"id":"b","texte":"Une preuve que Zadig a bien volé les animaux"},{"id":"c","texte":"Un hymne à la justice des rois de Babylone"},{"id":"d","texte":"Un ancêtre du raisonnement policier"}],"multiple":false},{"enonce":"Remets les trois moments de la scène dans l’ordre.","aide":"Il observe, il déduit, puis il en paie le prix.","type":"ordre","items":[{"id":"a","texte":"On l’accuse de vol"},{"id":"b","texte":"Il décrit les animaux sans les avoir vus"},{"id":"c","texte":"Zadig observe des traces dans le sable"}]}]}$ex$::jsonb,
