   $ex${"titre":"Tout mal engendre-t-il un bien ?","competence":"argumenter","situation":"Deux élèves se demandent ce que Voltaire pense de la providence dans Zadig. Lis le dialogue et la phrase de l’ermite, puis construis ton argument.","documents":[{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Elsa","emoji":"👧","cote":"gauche"},{"nom":"Karim","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Elsa","texte":"Voltaire pense que tout ce qui arrive est pour le mieux : il le dit dans Zadig."},{"qui":"Karim","texte":"Dans Zadig, oui : il est encore proche de l’optimisme de Leibniz. Il changera d’avis dans Candide."}]},{"id":"mal","type":"texte","genre":"recit","titre":"Les mots de l’ermite","blocs":["« Il n’y a point de mal dont il ne naisse un bien. »"],"source":"Voltaire, *Zadig* (1748), explication de l’ermite Jesrad"},{"id":"these","type":"tableau","titre":"Un argument à compléter","colonnes":["Thèse","Argument","Exemple"],"lignes":[["Le conte défend la providence","Chaque mal engendre un bien dans l’ordre général","?"]],"enteteLignes":true}],"questions":[{"enonce":"Touche les deux mots que la phrase de l’ermite oppose.","aide":"Un mot qui fait souffrir, un mot qui console.","type":"zone","document":"mal","multiple":true},{"enonce":"Touche le mot de Karim qui nomme la philosophie dont Voltaire est encore proche.","aide":"Karim cite le nom de Leibniz juste après.","type":"zone","document":"deb","multiple":false},{"enonce":"Quel exemple faut-il écrire dans la case « ? » du tableau ?","aide":"C’est l’ermite qui explique, par des actes surprenants.","type":"choix","options":[{"id":"a","texte":"Jesrad, ange déguisé en ermite, commet des actes apparemment monstrueux"},{"id":"b","texte":"Zadig renonce à Astarté et vit en ermite pour le reste de ses jours"},{"id":"c","texte":"Moabdar fait exécuter Zadig sur la place publique de Babylone"},{"id":"d","texte":"Sétoc vend Zadig comme esclave et le laisse mourir de faim"}],"multiple":false},{"enonce":"Range chaque fait : est-ce un malheur subi par Zadig, ou une cible de la satire de Voltaire ?","aide":"Les malheurs frappent le héros ; la satire vise la société.","type":"categories","categories":[{"id":"c0","texte":"Un malheur de Zadig"},{"id":"c1","texte":"Une cible de la satire"}],"items":[{"id":"i0","texte":"Les querelles religieuses"},{"id":"i1","texte":"La justice et ses procès absurdes"},{"id":"i2","texte":"Les courtisans jaloux"},{"id":"i3","texte":"Sa fuite et son esclavage"},{"id":"i4","texte":"Des trahisons amoureuses"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m6","m12"]},"explication":"La phrase oppose le **mal** et le **bien** : l’un engendre l’autre dans l’ordre général."},{"cle":{"type":"zone","ids":["m25"]},"explication":"Voltaire est encore proche de l’**optimisme** de Leibniz ; *Candide* le démolira après le tremblement de terre de Lisbonne."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Jesrad**, ange déguisé, commet sous ses yeux des actes **apparemment monstrueux**, puis explique que chaque mal engendre un bien."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c1","i3":"c0","i4":"c0"}},"explication":"Zadig **subit** trahisons, fuite et esclavage ; Voltaire **vise** la **justice**, les **courtisans** et les **querelles religieuses**."}]$ex$::jsonb),
