   $ex${"titre":"Deux jours, un métro en grève","competence":"se-reperer-temps","situation":"Zazie ne veut qu’une chose, prendre le métro. Suis ses deux jours à Paris, puis relie les personnages à leurs répliques.","documents":[{"id":"jours","type":"chaine","titre":"Les deux jours de Zazie","disposition":"colonne","noeuds":[{"id":"z1","texte":"Zazie débarque à Paris chez son oncle Gabriel"},{"id":"z2","texte":"Elle veut prendre le métro : il est en grève"},{"id":"z3","texte":"?"},{"id":"z4","texte":"Endormie, elle est ramenée à sa mère"},{"id":"z5","texte":"Elle répond : « J’ai vieilli. »"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"},{"de":"z4","a":"z5"}]}],"questions":[{"enonce":"Que faut-il écrire dans la case « ? » ?","aide":"Zazie ne prend pas le métro, mais elle visite Paris autrement.","type":"choix","options":[{"id":"a","texte":"Une bagarre générale à la brasserie, une virée dans Paris"},{"id":"b","texte":"Une enquête de police sur la disparition de Laverdure"},{"id":"c","texte":"Un voyage à Londres avec Charles et la veuve Mouaque"},{"id":"d","texte":"Un concours de danse où Gabriel remporte le premier prix"}],"multiple":false},{"enonce":"Touche l’étape où Zazie répond à la question « qu’est-ce que tu as fait ? ».","aide":"C’est la dernière de la chaîne.","type":"zone","document":"jours","multiple":false},{"enonce":"Relie chaque personnage à ce qui le distingue.","aide":"Chacun a un trait de comédie ou un rôle précis.","type":"association","gauche":[{"id":"g0","texte":"Laverdure"},{"id":"g1","texte":"Trouscaillon"},{"id":"g2","texte":"La veuve Mouaque"},{"id":"g3","texte":"Charles"}],"droite":[{"id":"d0","texte":"Il change sans cesse d’identité et de fonction"},{"id":"d1","texte":"Le chauffeur de taxi, ami de Gabriel"},{"id":"d2","texte":"Le perroquet qui répète « Tu causes, tu causes, c’est tout ce que tu sais faire »"},{"id":"d3","texte":"La compagne de route"}]}]}$ex$::jsonb,
