   $ex${"titre":"Doukipudonktan","competence":"analyser-texte","situation":"Deux élèves se disputent sur la langue du roman. Lis un passage écrit pour l’exercice, puis construis ton argument.","documents":[{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Samia","emoji":"👧","cote":"gauche"},{"nom":"Karim","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Samia","texte":"Le premier mot du roman, « Doukipudonktan », est une faute d’orthographe de Queneau."},{"qui":"Karim","texte":"Non : c’est du français parlé, transcrit tel qu’on l’entend."}]},{"id":"scene","type":"texte","genre":"recit","titre":"Sur le trottoir","blocs":["— Ouskonva ? demanda la gamine, plantée au milieu du trottoir.","— Tuvoirabyentô, répondit l’oncle, et ils s’en allèrent."],"source":"Texte écrit pour l’exercice, à la manière de Queneau (œuvre protégée : aucune citation)"}],"questions":[{"enonce":"Touche le mot de Karim qui qualifie le français transcrit par Queneau.","aide":"Karim l’oppose à une orthographe correcte.","type":"zone","document":"deb","multiple":false},{"enonce":"Touche les deux mots écrits comme on les prononce.","aide":"Lis-les à voix haute : tu entends une phrase entière.","type":"zone","document":"scene","multiple":true},{"enonce":"Que veut dire « Doukipudonktan », premier mot du roman ?","aide":"Prononce le mot à voix haute en le coupant en syllabes.","type":"choix","options":[{"id":"a","texte":"D’où qu’il vient donc tant ?"},{"id":"b","texte":"D’où qu’on part donc tant ?"},{"id":"c","texte":"D’où qu’ils puent donc tant ?"},{"id":"d","texte":"Dis-moi qui pue donc tant ?"}],"multiple":false},{"enonce":"Range chaque élément du roman : jeu sur la langue, ou intrigue ?","aide":"Le jeu travaille les mots ; l’intrigue raconte des événements.","type":"categories","categories":[{"id":"c0","texte":"Jeu sur la langue"},{"id":"c1","texte":"Intrigue"}],"items":[{"id":"i0","texte":"La transcription phonétique des mots"},{"id":"i1","texte":"La bagarre générale dans la brasserie"},{"id":"i2","texte":"Les jeux de mots et les parodies"},{"id":"i3","texte":"Les ruptures de registre"},{"id":"i4","texte":"Le métro est en grève"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m18"]},"explication":"Queneau écrit le français **parlé** en le transcrivant phonétiquement : c’est son « néo-français »."},{"cle":{"type":"zone","ids":["m0","m9"]},"explication":"**Ouskonva** (« où est-ce qu’on va ») et **Tuvoirabyentô** (« tu verras bientôt ») sont écrits **comme ils se prononcent**."},{"cle":{"type":"choix","ids":["c"]},"explication":"« Doukipudonktan » transcrit « **D’où qu’ils puent donc tant ?** » : le roman s’ouvre sur une phrase entendue, non écrite."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c0","i3":"c0","i4":"c1"}},"explication":"La **transcription**, les **jeux de mots** et les **ruptures de registre** jouent sur la langue ; la **grève** et la **bagarre** font l’intrigue."}]$ex$::jsonb),
