   $ex${"titre":"Qui nous parle de Manon ?","competence":"argumenter","situation":"Deux élèves se disputent : Manon est-elle une manipulatrice ? Lis un passage écrit pour l’exercice, puis tranche.","documents":[{"id":"aveu","type":"texte","genre":"recit","titre":"Des Grieux se justifie","blocs":["Je ne veux point m’excuser. J’avais dix-sept ans, un cœur trop tendre, et la fatalité fit le reste.","Manon était belle, et je ne vis rien d’autre : comment lui en vouloir ?"],"source":"Texte écrit pour l’exercice, à la manière de l’abbé Prévost"},{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Elsa","emoji":"👧","cote":"gauche"},{"nom":"Karim","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Elsa","texte":"Manon est une manipulatrice : elle ruine Des Grieux."},{"qui":"Karim","texte":"Mais on ne la voit que par les yeux de Des Grieux, qui se justifie."}]}],"questions":[{"enonce":"Touche le mot par lequel Des Grieux présente sa déchéance.","aide":"Il ne se dit pas coupable : il parle d’une force qui l’emporte.","type":"zone","document":"aveu","multiple":false},{"enonce":"Touche le mot de Karim qui montre le point de vue du roman.","aide":"Karim parle de la façon dont on voit Manon.","type":"zone","document":"deb","multiple":false},{"enonce":"Quelle lecture le dispositif du roman permet-il d’appuyer ?","aide":"Qui parle, après coup, à la première personne ?","type":"choix","options":[{"id":"a","texte":"Le roman est un témoignage neutre et sans point de vue"},{"id":"b","texte":"Le portrait de Manon est celui d’un homme qui l’aime et se justifie"},{"id":"c","texte":"Manon expose elle-même ses pensées à un marquis attentif"},{"id":"d","texte":"Le narrateur juge sévèrement Des Grieux à la fin du récit"}],"multiple":false},{"enonce":"Relie chaque procédé du roman à son effet.","aide":"Chaque procédé joue sur la façon dont on lit l’histoire.","type":"association","gauche":[{"id":"g0","texte":"Le récit rapporté par Renoncour"},{"id":"g1","texte":"La narration à la première personne, après coup"},{"id":"g2","texte":"Les coups de théâtre, évasions et duels"}],"droite":[{"id":"d0","texte":"Des Grieux se justifie et présente son sort comme une fatalité"},{"id":"d1","texte":"Une accélération qui ne laisse jamais le temps de juger"},{"id":"d2","texte":"Un récit dans un récit, qui donne la parole à Des Grieux"}]}]}$ex$::jsonb,
