   $ex${"titre":"Le pacte","competence":"analyser-texte","situation":"Raphaël vient de tout perdre. Lis le résumé de l’épisode du talisman, puis la phrase gravée sur la peau.","documents":[{"id":"pacte","type":"texte","genre":"recit","titre":"Chez l’antiquaire","blocs":["Raphaël, ruiné, a perdu son dernier napoléon au jeu. Chez l’antiquaire, il reçoit une peau d’onagre qui exauce tous les souhaits. Il souhaite aussitôt un banquet, et le trouve en sortant. Mais à chaque souhait, la peau rétrécit."],"source":"Résumé écrit pour l’exercice, d’après *La Peau de chagrin* de Balzac (1831)"},{"id":"inscr","type":"texte","genre":"source","titre":"La phrase gravée sur la peau","blocs":["« Si tu me possèdes, tu posséderas tout, mais ta vie m’appartiendra. »"],"source":"Honoré de Balzac, *La Peau de chagrin* (1831)"}],"questions":[{"enonce":"Touche le verbe qui dit ce que fait la peau à chaque souhait exaucé.","aide":"Elle devient plus petite chaque fois.","type":"zone","document":"pacte","multiple":false},{"enonce":"Touche le mot qui dit ce que le possesseur de la peau doit en échange.","aide":"Le prix est plus grand que de l’argent.","type":"zone","document":"inscr","multiple":false},{"enonce":"Remets les trois parties du roman dans l’ordre.","aide":"Le roman va de la rencontre avec la peau à la mort.","type":"ordre","items":[{"id":"a","texte":"La Femme sans cœur"},{"id":"b","texte":"L’Agonie"},{"id":"c","texte":"Le Talisman"}]},{"enonce":"Quelle loi du roman tient dans la phrase gravée ?","aide":"La peau exauce les souhaits, mais elle rétrécit.","type":"choix","options":[{"id":"a","texte":"Savoir, c’est pouvoir ; pouvoir, c’est jouir"},{"id":"b","texte":"Travailler, c’est mériter ; mériter, c’est recevoir"},{"id":"c","texte":"Vouloir, c’est vivre ; vivre, c’est se consumer"},{"id":"d","texte":"Aimer, c’est souffrir ; souffrir, c’est renoncer"}],"multiple":false}]}$ex$::jsonb,
